      "type": "result",
      "identifier": "result_010",
      "semantic_name": "module.google_search"
    }
  ],
  "constraints": [
    "Create the function binding with num_results defaulting to 5; defining the function does not execute its body."
  ],
  "metadata": {
    "source_span": {
      "file": "skill/scripts/search.py",
      "start_line": 6,
      "end_line": 16
    },
    "script_content": "def google_search(query, api_key, cse_id, num_results=5):\n    url = \"https://www.googleapis.com/customsearch/v1\"\n    params = {\n        'q': query,\n        'key': api_key,\n        'cx': cse_id,\n        'num': num_results\n    }\n    response = requests.get(url, params=params)\n    response.raise_for_status()\n    return response.json()\n",
    "source_actions": [
      {
        "ref": "define_google_search",
        "kind": "value",
        "source": {
